Query.SQL:

SELECT '{
          "param_integer_one": 1,
          "param_integer_two": 2,
          "param_integer3": 3
        }'::jsonb       AS param_one,
       '[
         {
           "param_integer_one": 1,
           "param_integer_two": 2,
           "param_integer3": 3
         },
         {
           "param_integer_one": 1,
           "param_integer_two": 2,
           "param_integer3": 3
         },
         {
           "param_integer_one": 1,
           "param_integer_two": 2,
           "param_integer3": 3
         }
       ]
       '::jsonb AS param_two
FROM GENERATE_SERIES(1, 20)
